// Build the fig CLI as a WASI module and vendor it into this package.
//
// Builds `fig-cli` (fig's Rust workspace, bindings/rust) for wasm32-wasip1
// with its `wasi-host` feature — so, unlike release-binaries.yml's
// standalone WASI artifact, this module carries no format and asks its host
// for every one — then copies the result into wasm/fig-wasi.wasm, and the
// languages bin/fig.mjs serves into lib/.
//
// Unlike the sibling `@diaryx/fig` library package, this ships the
// module as a real file rather than inlining it as base64: there's no
// bundler to appease here, just a plain `fs.readFileSync` from bin/fig.mjs.
import { execFileSync } from "node:child_process";
import { copyFileSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { stripTypeScriptTypes } from "node:module";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..", "..", "..");
const pkgDir = resolve(here, "..");
const workspace = repoRoot;

/** `cargo` in the Rust workspace, echoed. */
function cargo(args) {
  console.error(`· cargo ${args.join(" ")}`);
  execFileSync("cargo", args, { cwd: workspace, stdio: "inherit" });
}

// No format carried, and the host asked for each: bin/fig.mjs serves
// `@diaryx/fig`'s JavaScript languages to the CLI in-process
// (rust/fig-cli/src/host_languages.rs), as the library package serves them
// to its own module.
cargo(["build", "-p", "fig-cli", "--bin", "fig", "--profile", "wasm", "--target", "wasm32-wasip1", "--features", "wasi-host"]);

const wasmSrc = join(workspace, "target", "wasm32-wasip1", "wasm", "fig.wasm");
const wasmDestDir = join(pkgDir, "wasm");
mkdirSync(wasmDestDir, { recursive: true });
copyFileSync(wasmSrc, join(wasmDestDir, "fig-wasi.wasm"));
console.error("· wrote wasm/fig-wasi.wasm");

// The languages, the kit they are written with, and the wire's `handle`,
// from the library package beside this one — its sources, so nothing there
// needs building: `src/wire.ts` imports nothing and is erasable syntax, so
// Node's own type stripping makes it the JavaScript `dist/wire.js` would be. Copied rather than depended on, as the wasm is:
// the two packages release together, and this one needs nothing of the
// other at install time. Each file names the others by package subpath
// (`@diaryx/fig/kit/grammar`), which is rewritten to a relative path here,
// since nothing installs `@diaryx/fig` beside this package.
const lib = resolve(pkgDir, "..", "typescript");
const out = join(pkgDir, "lib");
rmSync(out, { recursive: true, force: true });
mkdirSync(join(out, "kit"), { recursive: true });
mkdirSync(join(out, "languages"), { recursive: true });

function relink(text, fromDir) {
  const to = (target) => {
    const rel = target.startsWith(fromDir + "/") ? "./" + target.slice(fromDir.length + 1) : "../" + target;
    return fromDir === "" ? "./" + target : rel;
  };
  return text
    .replace(/from "@diaryx\/fig\/helper"/g, `from "${to("wire.js")}"`)
    .replace(/from "@diaryx\/fig\/kit"/g, `from "${to("kit/index.js")}"`)
    .replace(/from "@diaryx\/fig\/kit\/(\w+)"/g, (_, m) => `from "${to(`kit/${m}.js`)}"`)
    .replace(/^\/\/# sourceMappingURL=.*$/m, "");
}

writeFileSync(join(out, "wire.js"), stripTypeScriptTypes(readFileSync(join(lib, "src", "wire.ts"), "utf8")));
// The JavaScript languages are the library package's `js/`. The native
// modules (`@diaryx/fig-<name>`) are not served to the CLI.
for (const [from, dir] of [["kit", "kit"], ["js", "languages"]]) {
  for (const f of readdirSync(join(lib, from)).filter((f) => f.endsWith(".js"))) {
    writeFileSync(join(out, dir, f), relink(readFileSync(join(lib, from, f), "utf8"), dir));
  }
}
// `kit/rules.js` imports `./rules-bytes.js`, the kit's rules as base64,
// which the library package's own build generates and git ignores — so a
// fresh checkout has no copy to take. Build it here, as that build does,
// rather than leaning on `../typescript` having been built first.
cargo(["rustc", "-p", "fig-kit-capi", "--profile", "wasm", "--crate-type", "cdylib", "--target", "wasm32-unknown-unknown"]);
const kitWasm = readFileSync(join(workspace, "target", "wasm32-unknown-unknown", "wasm", "fig_kit_capi.wasm"));
writeFileSync(
  join(out, "kit", "rules-bytes.js"),
  `// @generated by scripts/build-wasm.mjs — do not edit by hand.
// The kit's rules (rust/fig-kit-capi) compiled to WebAssembly, base64.
/** @type {string} */
export const BYTES = "${kitWasm.toString("base64")}";
`,
);
console.error("· wrote lib/ (the languages, the kit and the wire, from ../typescript)");
